import{_ as r,o,c as n,a0 as s}from"./chunks/framework.Czf8PZMA.js";const c=JSON.parse('{"title":"美国活跃模块化住宅供应商 SPEC 做法对标 — 联网调研报告","description":"","frontmatter":{},"headers":[],"relativePath":"guide/05-supplier-benchmark.md","filePath":"guide/05-supplier-benchmark.md","lastUpdated":null}'),a={name:"guide/05-supplier-benchmark.md"};function i(l,t,e,g,d,u){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="美国活跃模块化住宅供应商-spec-做法对标-—-联网调研报告" tabindex="-1">美国活跃模块化住宅供应商 SPEC 做法对标 — 联网调研报告 <a class="header-anchor" href="#美国活跃模块化住宅供应商-spec-做法对标-—-联网调研报告" aria-label="Permalink to &quot;美国活跃模块化住宅供应商 SPEC 做法对标 — 联网调研报告&quot;">​</a></h1><blockquote><p>调研员：Modular-Agent 联网调研 | 日期：2026-08-19 目的：为中国 Modular House 供应商，了解美国活跃竞品<strong>如何制作与发布产品 SPEC（技术规格文档）</strong>，含形态、MasterFormat 遵循、关键技术条文、合规背书与发布渠道。 数据来源：公开 web 检索（官网、Tech Library、ICC-ES、Arcat/ArchExpo、行业媒体等）。<strong>已核实</strong>与<strong>推测/未查实</strong>严格区分标注。</p></blockquote><hr><h2 id="〇、美国-modular-spec-做法的共性结论-先读这段" tabindex="-1">〇、美国 Modular SPEC 做法的共性结论（先读这段） <a class="header-anchor" href="#〇、美国-modular-spec-做法的共性结论-先读这段" aria-label="Permalink to &quot;〇、美国 Modular SPEC 做法的共性结论（先读这段）&quot;">​</a></h2><ol><li><strong>SPEC 形态分层</strong>：美国活跃供应商几乎从不只发一张&quot;产品规格表&quot;。常见组合是四件套——<strong>①产品 Spec Sheet（型号规格表）②Generic/标准 Plan Set（通用施工图集）③安装手册（Installation Manual）④工程/合规背书（ESR 评估报告 / HCD insignia / 字母机构 stamp）</strong>。建制派（如 VBC、Guerdon）再加 <strong>BIM 库、QTO、CSI 3-part specs、Shop Drawing</strong>。</li><li><strong>MasterFormat 遵循</strong>：真正面向建筑师/工程师的供应商会按 <strong>CSI MasterFormat</strong> 组织，核心落在 <strong>Division 13 Special Construction → 13 42 00 Building Modules</strong>（Building Modules 13 42 00）、配套 <strong>13 34 23 Fabricated Structures</strong>。但<strong>很多直接面向 C 端/ADU 客户的公司并不严格走 MasterFormat</strong>，而是用&quot;型号 + 平面 + 性能表&quot;的消费端口吻。<strong>是否 MASTERFORMAT 是区分&quot;C 端产品公司&quot;与&quot;建筑/GC 供货商&quot;的分水岭。</strong></li><li><strong>共性关键技术条文</strong>：尺寸（模块/户型面积/占地）、结构材料（ASTM/NDS/ACI/AISI/AISC）与体系、<strong>耐火等级（小时）</strong>、<strong>抗震/风载（引 DSA/OSHPD、或 ICC-ES AC156 评估、或地震区连接）</strong>、<strong>能耗（HERS / Title 24 / 气密 ACH50 / R 值）</strong>、工厂完成度（%）、连接与吊装、运输尺寸限制、保修年限。</li><li><strong>合规背书分级</strong>： <ul><li><strong>开源/低层产品</strong>（Boxabl 面板、Mighty 面板）→ <strong>ICC-ES ESR 评估报告</strong>（如 ESR-4725）+ EAD / AC156 抗震。</li><li><strong>封闭式体积模块</strong> → <strong>NTA 或州立第三方 plan review + 工厂检验</strong>，加州为 <strong>HCD insignia（Title 25）</strong>，商业模块<strong>工厂检率 25%</strong>（加州对 Casita Studio 已适用）。</li><li><strong>建筑级项目</strong>（VBC/Stack/Guerdon）→ <strong>项目级 plan review + 州政府盖章（stamping）+ 现场 AHJ</strong>，无标准一品一证 ESR。</li></ul></li><li><strong>发布渠道</strong>：官网&quot;技术库/Technical Library&quot;（最主流），另可上 <strong>ICC-ES 官网（ESR 免费下载）、Arcat、4specs、Sweets、ArchExpo（产品 Overview Book）</strong>。BIM 库（Revit 族）是建筑级供应商加分项。</li></ol><hr><h2 id="一、钢结构-集装箱式" tabindex="-1">一、钢结构 / 集装箱式 <a class="header-anchor" href="#一、钢结构-集装箱式" aria-label="Permalink to &quot;一、钢结构 / 集装箱式&quot;">​</a></h2><h3 id="_1-1-cimc-mbs-中集模块化" tabindex="-1">1.1 CIMC-MBS（中集模块化） <a class="header-anchor" href="#_1-1-cimc-mbs-中集模块化" aria-label="Permalink to &quot;1.1 CIMC-MBS（中集模块化）&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：无公开&quot;一品一证&quot;产品 Spec Sheet；官网走项目案例路线（Autodesk 中文案例：整体式钢结构集成模块建筑系统，可堆码 30 层、90% 装修工厂化、香港 InnoCell、竹篙湾隔离中心）。交付形态为<strong>项目级 BIM + Engineering Docs + Shop Drawing + 吊装手册</strong>。</li><li><strong>MasterFormat</strong>：未见公开明确引用；当建筑项目做 BIM 与 CSI 深化。</li><li><strong>关键技术条文</strong>：钢结构模块堆码层高（30 层）、工厂装修完成度、多国合规（美/欧/港）、连接节点。</li><li><strong>合规背书</strong>：项目属地合规（如香港、美国州级评审），未见公开 ICC-ES ESR。</li><li><strong>渠道</strong>：官网 + LinkedIn/BuiltWorlds + Autodesk 案例。<strong>公开 SPEC 形态：未查实/未公开。</strong></li></ul><h3 id="_1-2-volumetric-building-companies-vbc" tabindex="-1">1.2 Volumetric Building Companies (VBC) <a class="header-anchor" href="#_1-2-volumetric-building-companies-vbc" aria-label="Permalink to &quot;1.2 Volumetric Building Companies (VBC)&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：<strong>最接近建筑/GC 供货商的完整文档链</strong>。官网 How-it-Works 明确：Design Development（锁生产档期）→ <strong>BIM 模型 + QTO（工程量清单）输出</strong> → <strong>&quot;Construction Documentation&quot;阶段 Finalize the modular specifications</strong> → 工厂装配线 → <strong>各州主管机构盖章（modules inspected and stamped by state authorities）</strong> → 运输/吊装/施工。另有 <strong>Modular Pro Forma</strong>（财务测算下载）。</li><li><strong>MasterFormat</strong>：走项目级 CSI/BIM（Finalize modular specifications），隐含 MasterFormat/施工文档标准。</li><li><strong>关键技术条文</strong>：木框架 1-5 层、钢框架 1-22 层（REI60/90/120+190 耐火）、模块尺寸最小/最大值、自动化产线技术规格、BIM 驱动 QTO。</li><li><strong>合规背书</strong>：工厂内由州立权威盖章（state stamping）+ 第三方工厂检验；地区（Berwick PA / Tracy CA / Topole Poland）。</li><li><strong>渠道</strong>：官网 vbc.co（How-it-Works、Modular Pro Forma 门控下载）+ BuiltWorlds。<strong>无公开 ESR（项目级路线）。</strong></li></ul><h3 id="_1-3-katerra-对照-已破产" tabindex="-1">1.3 Katerra（对照：已破产） <a class="header-anchor" href="#_1-3-katerra-对照-已破产" aria-label="Permalink to &quot;1.3 Katerra（对照：已破产）&quot;">​</a></h3><ul><li><strong>状态</strong>：2021 年破产清算。原因：疫情、无法获得履约保函、融资失败。VBC 2021 收购其加州工厂资产。</li><li><strong>SPEC/教训</strong>：曾主打&quot;垂直整合 + DfMA/数字化制造&quot;，但<strong>制造可行性/成本验证不足</strong>。对标价值在<strong>反面教训</strong>：光有数字化/DfMA 愿景而无可持续制造现金流与合规背书，会崩盘。</li><li><strong>渠道</strong>：已下线。<strong>技术细节：未查实（已倒闭）。</strong></li></ul><h3 id="_1-4-untower" tabindex="-1">1.4 UnTower <a class="header-anchor" href="#_1-4-untower" aria-label="Permalink to &quot;1.4 UnTower&quot;">​</a></h3><ul><li><strong>状态</strong>：3D 混凝土打印高层/模块化背景信息间接命中，<strong>无独立 SPEC 文档可查</strong>。</li><li><strong>SPEC 形态/合规/渠道：未查实。</strong> 建议后续直接官网确认是否仍在运营。</li></ul><h3 id="_1-5-nxt-homes" tabindex="-1">1.5 NXT Homes <a class="header-anchor" href="#_1-5-nxt-homes" aria-label="Permalink to &quot;1.5 NXT Homes&quot;">​</a></h3><ul><li><strong>⚠️ 检索歧义已澄清</strong>：美国活跃的 &quot;NXT&quot; 是 <strong>Clayton（Athens）旗下的&quot;Manufactured &amp; Modular Farmhouse Style&quot;品牌</strong>（德州/俄克拉荷马等 Clayton 零售网络销售），<strong>非钢构科技公司</strong>。</li><li><strong>SPEC 形态</strong>：HUD/州 modular 框架下的<strong>型号平面 + 尺寸规格表（exterior-to-exterior 尺寸口径）+ 零售价目</strong>；规格随 SA/RCA 合同文档确认。</li><li><strong>MasterFormat</strong>：不适用（manufactured housing 走 HUD/州标，非 CSI）。</li><li><strong>合规背书</strong>：HUD 制造房屋标准 / 州 modular 认证（经 Clayton 零售体系），随合同附规格。</li><li><strong>渠道</strong>：官网 info.nxtathens.com。<strong>若用户指另一家科技型 NXT Homes，需再次定向检索。</strong></li></ul><hr><h2 id="二、木结构体积式" tabindex="-1">二、木结构体积式 <a class="header-anchor" href="#二、木结构体积式" aria-label="Permalink to &quot;二、木结构体积式&quot;">​</a></h2><h3 id="_2-1-plant-prefab-含旗下-livinghomes" tabindex="-1">2.1 Plant Prefab（含旗下 LivingHomes） <a class="header-anchor" href="#_2-1-plant-prefab-含旗下-livinghomes" aria-label="Permalink to &quot;2.1 Plant Prefab（含旗下 LivingHomes）&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：<strong>Plant Building System™ = Plant Panels™ + Plant Modules™</strong>。CAD 团队产出 <strong>3D 模型 + 生产 shop drawing + 卡车装载图（trucking load drawings）+ 详细安装手册（installation manuals）</strong>——这是&quot;完整 Doc Set + 物流/安装&quot;范本。</li><li><strong>MasterFormat</strong>：中高档 prefab 走标准施工文档/CAD 体系，隐含 MasterFormat。</li><li><strong>关键技术条文</strong>：Rialto / Tejon Ranch 工厂、木构面板 + 体积模块混合系统、生产图纸、运输装载、现场安装手册。</li><li><strong>合规背书</strong>：州/当地 AHJ 项目评审 + 工厂检验；LivingHomes 走 <strong>LEED（27 铂金 + 5 金）</strong> 可持续背书。</li><li><strong>渠道</strong>：官网（capabilities/工厂页）+ LivingHomes 产品页（LivingHome 7, 2230 SF）+ Z6 健康标准线。<strong>可下载安装手册/图纸（需联系/门控）。</strong></li></ul><h3 id="_2-2-autovol" tabindex="-1">2.2 Autovol <a class="header-anchor" href="#_2-2-autovol" aria-label="Permalink to &quot;2.2 Autovol&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：40 万平方英尺（Boise）<strong>轻木框架体积式</strong>；模块 1000+ 平方英尺；高完成度交付。规格为<strong>项目级工程文档包</strong>。</li><li><strong>MasterFormat</strong>：项目级（建筑供货商模式）。</li><li><strong>关键技术条文</strong>：模块尺寸、轻木框架、工厂完成度、体积式可堆叠。</li><li><strong>合规背书</strong>：州规章体积模块（工厂检验/州盖章）。</li><li><strong>渠道</strong>：官网 + 行业报道。<strong>公开一品 Spec Sheet：未查实。</strong></li></ul><h3 id="_2-3-guerdon-boise" tabindex="-1">2.3 Guerdon（Boise） <a class="header-anchor" href="#_2-3-guerdon-boise" aria-label="Permalink to &quot;2.3 Guerdon（Boise）&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：大型<strong>商业体积式模块</strong>（多户/员工住房/酒店）。交付为<strong>项目级模块规格 + 施工图纸 + 合规文件</strong>。</li><li><strong>MasterFormat</strong>：建筑级/酒店标准（CSI 体系）。</li><li><strong>关键技术条文</strong>：模块尺寸、钢结构/混合、多户与酒店单元、工厂完成度、运输/吊装。</li><li><strong>合规背书</strong>：州工厂检验 + 项目 AHJ。</li><li><strong>渠道</strong>：官网 + 行业报道。<strong>公开一品 Spec Sheet：未查实。</strong></li></ul><h3 id="_2-4-abodu-adu-供应商" tabindex="-1">2.4 Abodu（ADU 供应商） <a class="header-anchor" href="#_2-4-abodu-adu-供应商" aria-label="Permalink to &quot;2.4 Abodu（ADU 供应商）&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：C 端 ADU“产品线”路线：<strong>340–800 SF、Studio–2BR、单层</strong>；交付为<strong>型号平面 + 尺寸/能效规格 + 安装概览 + turnkey（含 permitting/工程/基础/utility/吊装）</strong>。</li><li><strong>MasterFormat</strong>：不严格遵循（消费端口吻为主）。</li><li><strong>关键技术条文</strong>：户型面积/房型/层数、工厂完成度、site 基础/utility 要求、turnkey 服务清单。</li><li><strong>合规背书</strong>：加州 ADU 路径 + 当地 AHJ + 州 modular 要求（体积模块需 HCD 项）。</li><li><strong>渠道</strong>：官网产品页 + 行业对比文章（Prefab ADU 评测）。</li></ul><h3 id="_2-5-mighty-buildings-3d-打印-材料挤出-2025-传出待售" tabindex="-1">2.5 Mighty Buildings（3D 打印/材料挤出，2025 传出待售） <a class="header-anchor" href="#_2-5-mighty-buildings-3d-打印-材料挤出-2025-传出待售" aria-label="Permalink to &quot;2.5 Mighty Buildings（3D 打印/材料挤出，2025 传出待售）&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：<strong>Mighty Kit System™（工厂 3D 打印面板 + 现场组装）+ 6 款 ADU 型号</strong>。核心是 <strong>3D 打印 Mighty Panel（100% 聚合物复合材料，集成结构+保温+MEP+空气/水/防火屏障+内外饰面）</strong>。</li><li><strong>MasterFormat</strong>：中高端 prefab，隐含施工文档体系。</li><li><strong>关键技术条文</strong>：<strong>LUMUS™/Light Stone Material（UV 固化热固复合材料，5 倍混凝土抗拉/弯强、轻约 30%、含约 60% 回收料）</strong>；面板仅 8 英寸厚 5 层材料、PU 泡棉保温定制 R 值、环氧底漆+丙烯酸面漆（无空气/水屏障）；全电动。</li><li><strong>合规背书</strong>：<strong>EAD 标准 EAD 040287-00-0404 评估 + 按 ICC-EO AC156 抗震评估</strong>、ICC-ES ESR 路径（面板类）。</li><li><strong>渠道</strong>：官网 Product/Technology 页 + ArchPaper/ACMA 案例。<strong>公开 ESR 具体编号：未逐条核实。</strong></li></ul><hr><h2 id="三、轻质-预制面板-单元" tabindex="-1">三、轻质 / 预制面板 + 单元 <a class="header-anchor" href="#三、轻质-预制面板-单元" aria-label="Permalink to &quot;三、轻质 / 预制面板 + 单元&quot;">​</a></h2><h3 id="_3-1-boxabl-本族最强-技术库-范本" tabindex="-1">3.1 Boxabl（本族最强&quot;技术库&quot;范本） <a class="header-anchor" href="#_3-1-boxabl-本族最强-技术库-范本" aria-label="Permalink to &quot;3.1 Boxabl（本族最强&quot;技术库&quot;范本）&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：<strong>官网设有 Technical Library，公开成套下载</strong>：每型号 <strong>Casita Studio/One Bedroom/Two Bedroom Specifications（Spec Sheet，约 2.4 MB）</strong> + <strong>Generic Plan Set（Casita Two Bedroom 2.4MB / Studio 8.7MB / Standard Generic Plans）</strong> + <strong>Installation Guide（5.2MB）</strong> + <strong>Panel Certification（3.1MB）</strong> + <strong>BabyBox Specifications</strong>。还有型号 Specs（如 BXB-000009）。</li><li><strong>MasterFormat</strong>：部分遵循（Casita 有 Generic Plan Set 面向 permit）；消费端口吻为主。</li><li><strong>关键技术条文</strong>：19×19ft/约 361 SF、钢框折叠面板、<strong>折叠后 8.5ft 宽可免特殊许可合法公路运输</strong>、100A 120/240V 全电、30 加仑电热水器、R 值/气密、防火/防涝/飓风级材料、太阳能兼容、一天装毕、$140k turnkey。</li><li><strong>合规背书</strong>：<strong>ICC-ES ESR-4725（2021/2018 IBC &amp; IRC：结构性能、热障、防风雨层、抗震）</strong> + Panel Certification 文档；<strong>加州对 Casita 已按商业模块/面板降至 25% 检率</strong>（Title 25 体系）。</li><li><strong>渠道</strong>：官网 boxabl.com/technical-docs（公开下载，不需门控）+ Scribd（型号 Specs）等镜像。</li></ul><h3 id="_3-2-cover-cloud-apartments" tabindex="-1">3.2 Cover（Cloud Apartments） <a class="header-anchor" href="#_3-2-cover-cloud-apartments" aria-label="Permalink to &quot;3.2 Cover（Cloud Apartments）&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：<strong>专利 snap installment 技术</strong>（嵌线管道的预制木+钢单元快接 / quick-connect MEP），面向多户。交付项目级。</li><li><strong>MasterFormat</strong>：建筑/多户体系。</li><li><strong>关键技术条文</strong>：预制木+钢单元、快接 MEP、多户组装。</li><li><strong>合规背书</strong>：加州/州 modular 工厂检验。</li><li><strong>状态</strong>：运营/被收购情况需官网确认。<strong>公开一品 Spec Sheet：未查实。</strong></li></ul><h3 id="_3-3-blu-homes" tabindex="-1">3.3 Blu Homes <a class="header-anchor" href="#_3-3-blu-homes" aria-label="Permalink to &quot;3.3 Blu Homes&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：<strong>发布《Specification Guide》（PDF）</strong> + <strong>《Blu Homes Overview Book》（ArchExpo 可查）</strong>。钢框折叠房。</li><li><strong>MasterFormat</strong>：中高档 prefab，规范工程图纸。</li><li><strong>关键技术条文</strong>：<strong>R-38 SIP 屋面、外墙 R-28、楼板 R-32、直立锁边金属屋面、Venmar HRV、水暖/多联机 HVAC 选项</strong>；<strong>气密 6.0–4.0 ACH50</strong>；节能约 50–70%；折叠钢框（运输+现场展开）；多用 SGH 结构工程（覆盖工厂制造、折叠、运输、现场展开全流程图纸逻辑）。LEED certifiable。</li><li><strong>合规背书</strong>：LEED 可持续背书 + 项目级 SGH 结构工程设计（非 ESR）。</li><li><strong>渠道</strong>：官网 + ArchExpo/GreenBuildingAdvisor。</li></ul><h3 id="_3-4-livinghomes-plant-旗下" tabindex="-1">3.4 LivingHomes（Plant 旗下） <a class="header-anchor" href="#_3-4-livinghomes-plant-旗下" aria-label="Permalink to &quot;3.4 LivingHomes（Plant 旗下）&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：随 Plant Prefab 的 Plant Building System 交付完整 Doc Set（见 2.1）。</li><li><strong>关键技术条文</strong>：LivingHome 7（2230 SF）、Z6 健康可持续框架、<strong>27 个 LEED 铂金 + 5 个金</strong>。</li><li><strong>合规背书</strong>：LEED 为主。</li><li><strong>渠道</strong>：官网产品页。</li></ul><hr><h2 id="四、酒店-多户" tabindex="-1">四、酒店 / 多户 <a class="header-anchor" href="#四、酒店-多户" aria-label="Permalink to &quot;四、酒店 / 多户&quot;">​</a></h2><h3 id="_4-1-stack-modular" tabindex="-1">4.1 Stack Modular <a class="header-anchor" href="#_4-1-stack-modular" aria-label="Permalink to &quot;4.1 Stack Modular&quot;">​</a></h3><ul><li><strong>SPEC 形态</strong>：<strong>钢结构体积式（steel volumetric）</strong>，建筑级项目文档。实例 the Walk Norwalk：516 模块、373 户、2 栋建筑（7/5 层）、总 68 万 SF、含 58 套可负担房、2024 年 1BR/2 模块样品房。交付尺寸/结构/连接/吊装规格。</li><li><strong>MasterFormat</strong>：建筑/多户标准。</li><li><strong>关键技术条文</strong>：钢结构体积模块尺寸、模块-核心筒/模块间连接（抗震关键）、防火（模块间火焰蔓延、B3 结构稳定等国际研究共识）、吊装/运输序列。</li><li><strong>合规背书</strong>：项目级 + 州/当地评审；参与 UBC Smart Structures 高层钢模块抗震研究（WSP/Stantec/Bird 合作）。</li><li><strong>渠道</strong>：官网案例页 + 学术研究引用。</li></ul><h3 id="_4-2-nuralite" tabindex="-1">4.2 Nuralite <a class="header-anchor" href="#_4-2-nuralite" aria-label="Permalink to &quot;4.2 Nuralite&quot;">​</a></h3><ul><li><strong>状态</strong>：<strong>未获针对性命中</strong>，可能为小型/已停业公司。</li><li><strong>SPEC 形态/合规/渠道：未查实。</strong> 建议确认公司名/拼写后重新定向。</li></ul><h3 id="_4-3-cubico" tabindex="-1">4.3 Cubico <a class="header-anchor" href="#_4-3-cubico" aria-label="Permalink to &quot;4.3 Cubico&quot;">​</a></h3><ul><li><strong>状态</strong>：<strong>未获针对性命中</strong>，可能为小型/已停业公司。</li><li><strong>SPEC 形态/合规/渠道：未查实。</strong> 建议确认后重新定向。</li></ul><hr><h2 id="五、对标小结-给中国供应商的启示" tabindex="-1">五、对标小结（给中国供应商的启示） <a class="header-anchor" href="#五、对标小结-给中国供应商的启示" aria-label="Permalink to &quot;五、对标小结（给中国供应商的启示）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>公司</th><th>典型 SPEC 形态</th><th>MasterFormat?</th><th>关键背书</th><th>公开渠道</th></tr></thead><tbody><tr><td>CIMC-MBS</td><td>项目级 BIM+Doc（未公开一品Spec）</td><td>隐含</td><td>项目属地</td><td>官网+案例</td></tr><tr><td>VBC</td><td>BIM+QTO+Finalize specs+州盖章</td><td>是(建筑级)</td><td>州 stamping</td><td>官网门控</td></tr><tr><td>Katerra</td><td>已破产（反面教材）</td><td>—</td><td>—</td><td>下线</td></tr><tr><td>UnTower</td><td>未查实</td><td>—</td><td>—</td><td>—</td></tr><tr><td>NXT(Clayton)</td><td>型号平面+尺寸+合同规格</td><td>否(HUD州标)</td><td>HUD/州modular</td><td>官网+零售</td></tr><tr><td>Plant Prefab</td><td>3D+shop drawing+装载图+安装手册</td><td>隐含</td><td>州AHJ+LEED</td><td>官网</td></tr><tr><td>Autovol</td><td>项目级工程包</td><td>隐含</td><td>州检验</td><td>官网</td></tr><tr><td>Guerdon</td><td>项目级模块规格</td><td>建筑级</td><td>州检验</td><td>官网</td></tr><tr><td>Abodu</td><td>型号+平面+turnkey</td><td>否(消费端)</td><td>州AHJ/ADU</td><td>官网</td></tr><tr><td>Mighty Buildings</td><td>面板型号+材料/抗震背书</td><td>隐含</td><td>EAD040287+AC156</td><td>官网+媒体</td></tr><tr><td><strong>Boxabl</strong></td><td><strong>Spec Sheet+Plan Set+安装手册+Panel Cert(ESR)</strong></td><td>部分</td><td><strong>ESR-4725+25%检率</strong></td><td><strong>Technical Library公开</strong></td></tr><tr><td>Cover</td><td>snap单元+快接MEP(项目)</td><td>建筑级</td><td>州检验</td><td>官网(需确认)</td></tr><tr><td>Blu Homes</td><td><strong>Specification Guide PDF+Overview Book</strong></td><td>隐含</td><td>LEED+SGH工程</td><td>官网+ArchExpo</td></tr><tr><td>LivingHomes</td><td>随Plant Doc Set</td><td>隐含</td><td>LEED铂金/金</td><td>官网</td></tr><tr><td>Stack Modular</td><td>钢结构体积+连接/耐火规格</td><td>建筑级</td><td>项目级+抗震研究</td><td>官网+学术</td></tr><tr><td>Nuralite / Cubico</td><td>未查实</td><td>—</td><td>—</td><td>—</td></tr></tbody></table><p><strong>给中国供应商的核心对标建议</strong>：</p><ol><li><strong>公开&quot;技术库&quot;</strong>：像 Boxabl 一样把 <strong>Spec Sheet + Generic Plan Set + 安装手册 + 认证文件</strong>做成官网公开下载区——这是 C 端与 permit 双赢，比只有&quot;项目案例&quot;更能被美国买家/建筑师迅速采纳入规格书。</li><li><strong>走合规背书补齐信任</strong>：低层/面板产品申请 <strong>ICC-ES ESR</strong>（如 ESR-4725 模板），体积式进入加州要对接 <strong>HCD insignia / Title 25 工厂检率体系</strong>，建筑级要有 <strong>州第三方 plan review + 盖章</strong>。</li><li><strong>按 MasterFormat 13 42 00 Building Modules / 13 34 23 组织一份 CSI 3-part spec</strong>，并出 BIM 族——这是打进美国建筑师/MEP 工作流的关键，也是多数竞品（除 VBC/Blu）仍较弱的空白可抢占点。</li><li><strong>技术条文覆盖四大硬指标</strong>：尺寸与占地、耐火、抗震（含高烈度区连接设计）、能耗（HERS/Title 24/ACH50/R 值），并明确写出工厂完成度、连接与吊装、运输宽度限制、保修年限。</li></ol><hr><p><em>调研说明：本报告基于公开 web 检索，Nuralite、Cubico、UnTower、CIMC-MBS 公开一品 SPEC 形态未能核实，已如实标注；NXT 存在公司名歧义，已按美活跃实体（Clayton NXT）处理。</em></p>',54)])])}const S=r(a,[["render",i]]);export{c as __pageData,S as default};
